/**************************************************************************/
/*                                                                        */
/*  BOARD SUPPORT                                          RELEASE        */
/*                                                                        */
/*    tcm.h                                            Cortex-R52/GNU     */
/*                                                           6.5.2        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Frederic Desbiens, Eclipse Foundation                               */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Tightly-coupled memory on the S32Z280.  This header is the reading  */
/*    half: what the hardware reports about itself.  Enabling comes next  */
/*    and depends on what these reads say.                                */
/*                                                                        */
/*  WHERE THE FACTS COME FROM                                             */
/*                                                                        */
/*    Cortex-R52 TRM r1p3 (100026_0103_00_en), section 3.3.94, table      */
/*    3-136.  IMP_ATCMREGIONR, IMP_BTCMREGIONR and IMP_CTCMREGIONR are    */
/*    at MRC/MCR p15, 0, <Rt>, c9, c1, {0,1,2} and are laid out:          */
/*                                                                        */
/*      [31:13] BASEADDRESS   bits [31:13] of the TCM base address        */
/*      [12:9]  RES0                                                     */
/*      [8]     WAITSTATES    wait states for TCM accesses               */
/*      [7]     RES0                                                     */
/*      [6:2]   SIZE          size indicator, read-only in effect        */
/*      [1]     ENABLEEL2     enable at EL2                              */
/*      [0]     ENABLEEL10    enable at EL1 and EL0                      */
/*                                                                        */
/*    ⚠ BASEADDRESS is [31:13], not [31:12].  IMP_PERIPHPREGIONR uses    */
/*    [31:12] and inferring the same here would be wrong by one bit --   */
/*    the same class of mistake that made PRBAR silently drop XN.  The    */
/*    base is therefore 8KB-aligned, not 4KB.                            */
/*                                                                        */
/*    SIZE encodings: 0 none, 4 8KB, 5 16KB, 6 32KB, 7 64KB, 8 128KB,    */
/*    9 256KB, 10 512KB, 11 1MB.                                         */
/*                                                                        */
/*    "At reset all bits are 0 apart from SIZE and WAITSTATES", unless    */
/*    CFGTCMBOOTx is high, which resets the ATCM enables to 1.  So a      */
/*    part that has not been told otherwise has every TCM based at 0 with */
/*    both enables clear, which is exactly why reads of the documented    */
/*    TCM windows fault on this board.                                    */
/*                                                                        */
/*    IMP_MEMPROTCTLR is at p15, 1, <Rt>, c9, c1, 2 (TRM 3.3.76, table    */
/*    3-114): RAMPROTIMP [4] says whether RAM protection exists at all,   */
/*    RAMPROTEN [0] whether it is on, and RAMPROTEN is ignored when       */
/*    RAMPROTIMP is 0.                                                   */
/*                                                                        */
/*    S32Z2 reference manual: TCMA 64KB with 1 wait state, TCMB 16KB with */
/*    0, TCMC 16KB with 1, per core.  Those give expected SIZE values of  */
/*    7, 5 and 5, which is a cross-check between the two documents and    */
/*    the silicon rather than a restatement of either.                    */
/*                                                                        */
/*  WHY ENABLING IS NOT ENOUGH                                            */
/*                                                                        */
/*    TRM section 6.2.2: the ECC bits in TCM RAM are not initialised by   */
/*    the processor, and a location must be written before it is read     */
/*    with ECC enabled.  An uninitialised read reports an error, which    */
/*    looks exactly like "the TCM is not accessible" and would send the   */
/*    reader back to these region registers, which were already right.    */
/*                                                                        */
/*    The preload widths are not uniform: BTCM and CTCM take STR, STRD    */
/*    or STM at 32-bit alignment, but ATCM needs STRD or STM at 64-bit    */
/*    alignment.  A C loop storing 32-bit words would leave ATCM's check  */
/*    bits invalid.                                                      */
/*                                                                        */
/**************************************************************************/

#ifndef TCM_H
#define TCM_H

/* One bank's reported configuration, decoded from its region register.  */

typedef struct
{
    unsigned long   raw;            /* register as read                     */
    unsigned long   base;           /* BASEADDRESS << 13                    */
    unsigned int    size_field;     /* SIZE, as encoded                     */
    unsigned long   size_bytes;     /* decoded, 0 if the encoding is unknown */
    unsigned int    wait_states;
    unsigned int    enable_el2;
    unsigned int    enable_el10;
} tcm_bank_t;

/* Read and decode one bank.  Index 0 is ATCM, 1 BTCM, 2 CTCM; any other
   index yields a zeroed structure.  */

void tcm_read_bank(unsigned int index, tcm_bank_t *bank_ptr);

/* IMP_MEMPROTCTLR, raw.  */

unsigned long tcm_read_memprotctlr(void);

/* Whether RAM protection is implemented, and whether it is enabled.  Both are
   decoded from IMP_MEMPROTCTLR, and the second is meaningless when the first
   is zero -- the TRM says the design behaves as if RAMPROTEN were 0.  */

unsigned int tcm_ecc_implemented(void);
unsigned int tcm_ecc_enabled(void);

/**************************************************************************/
/*  ENABLING                                                              */
/*                                                                        */
/*    Constraints, all from Cortex-R52 TRM r1p3 section 6.2 and 3.3.94:    */
/*                                                                        */
/*    - The base address must be SIZE-ALIGNED, not merely 8KB-aligned as   */
/*      the BASEADDRESS field's width alone would suggest.                */
/*    - A disabled TCM's base address is UNKNOWN, not zero, so every bank  */
/*      must be programmed explicitly rather than adjusted from what it    */
/*      appears to hold.                                                  */
/*    - "Before using the TCM you must program MPU regions to cover the    */
/*      TCM regions to give access."  An enabled TCM with no MPU region    */
/*      still faults once the MPU is on.                                  */
/*    - An enabled TCM always behaves as Non-cacheable Non-shareable       */
/*      Normal memory whatever the MPU says; the MPU supplies only the     */
/*      permissions.  So the MPU region's attribute index is irrelevant    */
/*      here and its AP and XN bits are not.                              */
/*    - With ECC on, every location must be written before it is read.     */
/*                                                                        */
/**************************************************************************/

/* Program one bank's base and enable it at both exception levels.  Returns 1 on
   success, 0 if the index is out of range, the bank reports no size, or the base
   is not size-aligned.  Verifies by reading the register back.  */

unsigned int tcm_enable(unsigned int index, unsigned long base);

/* Write every location of a bank so its ECC check bits become valid.  The store
   width is chosen from the bank: index 0 is ATCM and needs 64-bit stores, and
   the others take 32-bit.  Must be called while the bank is enabled and
   accessible, and before anything reads it.  */

void tcm_preload(unsigned int index, unsigned long base, unsigned long bytes);

#endif
